import{c as a,Q as t,j as n,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse(`{"title":"Stop Being the Loop. Here's How to Make Claude Work While You Sleep.","description":"","frontmatter":{"url":"https://x.com/raytar/status/2069212188619805179","title":"Stop Being the Loop. Here's How to Make Claude Work While You Sleep.","author":"Raytar","archived":"2026-06-27T00:00:00.000Z","handle":"@Raytar","published":"2026-06-23T00:00:00.000Z","stats":"300 likes · 40 retweets · 1129 bookmarks · 1063059 views","tags":["loop-engineering","loop-charter","goal-vs-loop","state-file","cron-vs-loop","boris-cherny"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-23-@Raytar-805179.md","filePath":"research/tweets/2026-06-23-@Raytar-805179.md","lastUpdated":1785909234000}`),s={name:"research/tweets/2026-06-23-@Raytar-805179.md"};function i(l,e,r,p,h,d){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="stop-being-the-loop-here-s-how-to-make-claude-work-while-you-sleep-—-raytar" tabindex="-1">Stop Being the Loop. Here&#39;s How to Make Claude Work While You Sleep. — @Raytar <a class="header-anchor" href="#stop-being-the-loop-here-s-how-to-make-claude-work-while-you-sleep-—-raytar" aria-label="Permalink to &quot;Stop Being the Loop. Here&#39;s How to Make Claude Work While You Sleep. — @Raytar&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/raytar/status/2069212188619805179" target="_blank" rel="noreferrer">https://x.com/raytar/status/2069212188619805179</a><strong>作者</strong>：Raytar（@Raytar） <strong>發布日期</strong>：2026-06-23 <strong>收錄日期</strong>：2026-06-27 <strong>類型</strong>：Twitter Article <strong>統計</strong>：300 likes · 40 retweets · 1129 bookmarks · 1063059 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>The person who built Claude Code at Anthropic stopped prompting Claude. His name is Boris Cherny. In June 2026 he said it out loud: &quot;I don&#39;t prompt Claude anymore.&quot; Loops prompt Claude for him. His actual job now is writing loops. That sounds like a flex. But no. It&#39;s the biggest shift in how people use Claude and ChatGPT right now. You&#39;ve probably heard the phrase. Almost nobody does it yet. Here is how you work right now.</p><ul><li>You type a prompt.</li><li>Claude edits a file.</li><li>You run the test.</li><li>It breaks.</li><li>You paste the error back.</li><li>It tries again. Twenty minutes later you realize you&#39;ve been babysitting the exact thing you wanted to hand off. You are the loop. You&#39;re the one checking the work and deciding the next step, every single time. That is the job a loop takes over.</li></ul><hr><h2 id="one-example-shows-the-whole-difference" tabindex="-1">One example shows the whole difference <a class="header-anchor" href="#one-example-shows-the-whole-difference" aria-label="Permalink to &quot;One example shows the whole difference&quot;">​</a></h2><p>Ask Claude to write you a one page brief on any topic. Simple task. It writes something clean and confident, with sources at the bottom.</p><p>[圖 1]</p><p>Now read the sources. Some of them are fake(!!!). Claude made them up and has no idea it did. They look real. The links go nowhere, or they go somewhere that doesn&#39;t say what Claude claimed. This is the quiet way Claude burns you, and a single prompt can never catch it, because Claude stays confident it&#39;s right until something opens the link. Now run it as a loop instead. Same brief, but you add a bar it can measure:</p><blockquote><p>every claim needs at least three sources, and every link has to open to a real page that backs up the claim. Watch what happens. Claude writes the brief, then goes link by link. It opens each one. It throws out the dead ones and the fake ones. It finds real replacements. It keeps checking until every single source on the page is something you can open. Then it stops. It never gets bored. It never skips the boring ones. Here&#39;s how you&#39;d write that in Claude Code. Don&#39;t worry about the command yet, I break it down below:</p></blockquote><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/goal write a one page brief on [your topic]</span></span>
<span class="line"><span>where every claim has at least three sources and</span></span>
<span class="line"><span>every link opens to a real page that supports the claim. </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Open each link to confirm it before you call it done.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Replace any source that is dead or does not back up the claim.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Stop only when every source on the page checks out.</span></span></code></pre></div><h1 id="what-a-loop-is" tabindex="-1">What a loop is <a class="header-anchor" href="#what-a-loop-is" aria-label="Permalink to &quot;What a loop is&quot;">​</a></h1><p>[圖 2]</p><p>A loop is a small system that prompts Claude for you, over and over, until a job is done. Every loop, no matter how fancy, is the same five beats:</p><ol><li>Find the work. Open tasks, failing tests, unread emails, files in a folder.</li><li>Do it. Claude handles one item at a time, like you would by hand.</li><li>Check itself. A second pass confirms the work is done and correct, not just produced.</li><li>Remember. It writes down what&#39;s finished, so it never repeats work or loses its place.</li><li>Go again. It repeats until nothing&#39;s left, then stops or pings you. One line to keep: prompting is doing the work. Loop engineering is managing the worker.</li></ol><h2 id="isn-t-this-just-a-scheduled-task" tabindex="-1">&quot;Isn&#39;t this just a scheduled task?&quot; <a class="header-anchor" href="#isn-t-this-just-a-scheduled-task" aria-label="Permalink to &quot;&quot;Isn&#39;t this just a scheduled task?&quot;&quot;">​</a></h2><p>[圖 3]</p><p>Good question. No. You can already make your computer run the same thing every morning at 8am. That&#39;s a cron job. It&#39;s older than most of us. It runs a fixed script. Same steps, every time, no thinking. A loop is different because of one thing: there&#39;s a decision-maker inside it. A cron job runs a script. A loop runs Claude. Claude looks at the current situation, picks the next action, does it, checks the result, and then decides what to do next. Keep going. Try again. Undo. Stop. That decision in the middle is the entire point. A script can&#39;t look at a broken test and figure out a different fix. Claude can. This only became possible once Claude and ChatGPT got good enough to make real judgment calls mid-job.</p><h2 id="the-two-commands-that-run-a-loop" tabindex="-1">The two commands that run a loop <a class="header-anchor" href="#the-two-commands-that-run-a-loop" aria-label="Permalink to &quot;The two commands that run a loop&quot;">​</a></h2><p>[圖 4]</p><p>Here&#39;s where most people go wrong. You don&#39;t build a loop by typing &quot;do this in a loop&quot; into a normal chat. Claude Code has two commands built in, and which one you reach for depends on the kind of loop you need.</p><ol><li>/goal is the loop that works until it&#39;s done. But obviously not that kind of goal. xD You saw /goal up in the brief example. You type it, then describe what &quot;done&quot; looks like. Claude keeps working, turn after turn, on its own. After every turn, a second copy of Claude quietly checks: are we at the goal yet? If not, it tells the first one why, and the work continues. The moment the goal is met, the loop stops by itself. That self-check after every turn is the whole difference between a real loop and a prompt that runs once and hopes. Use /goal when there&#39;s a finish line. Work until this is true.</li><li>/loop is the loop that repeats on a rhythm. Reach for this when the job isn&#39;t &quot;finish a pile&quot; but &quot;keep an eye on something.&quot; You tell it how often and what to do, and Claude re-runs it for you.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/loop 30m check whether my live site is back up by loading the homepage.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The moment it returns a normal page, tell me and stop checking.</span></span></code></pre></div><p>The 30m means every 30 minutes. You can also just say &quot;every morning, triage my inbox&quot; and Claude will schedule it. Use /loop when there&#39;s no finish line, just a beat. Check this again and again. Most of the strong loops you&#39;ll build start with /goal. These are recent Claude Code features, so if you don&#39;t see the commands, update Claude Code and they&#39;ll show up.</p><h2 id="your-first-loop-ready-to-paste" tabindex="-1">Your first loop, ready to paste <a class="header-anchor" href="#your-first-loop-ready-to-paste" aria-label="Permalink to &quot;Your first loop, ready to paste&quot;">​</a></h2><p>A one line goal is plenty for a small job. For a bigger job with lots of steps, you hand Claude a full charter: where to find the work, how to check itself, how to remember, when to stop. Fill in the brackets and paste this into Claude Code: You are running as a loop, not answering one prompt. Here is your charter.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GOAL</span></span>
<span class="line"><span>[Describe the finished state in one or two sentences. </span></span>
<span class="line"><span>Be specific about what DONE looks like, and make it something you can measure. </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Example: &quot;Every product page in /pages has the new pricing and every link opens.&quot;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>WHERE THE WORK IS</span></span>
<span class="line"><span>[Tell Claude where to look.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Examples: &quot;Scan the /pages folder for files with old pricing.&quot; Or &quot;Read TODO.md and treat each unchecked box as a task.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot; Or &quot; Check my connected task board for items tagged ai.&quot;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HOW TO WORK</span></span>
<span class="line"><span>- Do one item at a time. Finish it fully before starting the next.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Match the patterns you find in existing files. Do not invent new ones.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- If an item needs a decision only I can make (spending money, deleting things, emailing a person), stop on that item, add it to a &quot;needs me&quot; list, and move to the next one.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HOW TO CHECK YOURSELF</span></span>
<span class="line"><span>After each item, prove it is done before you mark it done.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Pick what fits: &quot;run the tests&quot; / &quot;re-read the file and confirm it meets the goal&quot; / &quot;open the link and confirm it loads.&quot; Checking means evidence, not confidence.]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If the check fails, fix it and check again. Three tries per item, then log it as blocked and move on.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HOW TO REMEMBER</span></span>
<span class="line"><span>Keep a file called LOOP-STATE.md. </span></span>
<span class="line"><span>After each item, write the item name, its status (done / blocked / needs me), what you changed, and anything the next run should know.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Read this file FIRST every run so you never redo finished work.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>WHEN TO STOP</span></span>
<span class="line"><span>Stop when every item is done or logged as blocked, or when you have finished [N] items this run.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Then give me a short report: what got done, what is blocked, what needs my call.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Start by reading LOOP-STATE.md if it exists, then find the work.</span></span></code></pre></div><p>The state file is the quiet hero. Without it, every run starts from zero. With it, the loop picks up exactly where it left off, even when it runs on a schedule.</p><h2 id="when-not-to-build-a-loop" tabindex="-1">When not to build a loop <a class="header-anchor" href="#when-not-to-build-a-loop" aria-label="Permalink to &quot;When not to build a loop&quot;">​</a></h2><blockquote><p>Loops are not free and not for everything. Three honest things before you start.</p></blockquote><ol><li>One-off tasks don&#39;t need a loop. If the job is a single answer, a plain prompt is faster. Loops earn their setup cost on work that repeats or has many pieces.</li><li>Loops cost more. A loop that checks itself and retries is running Claude several times per item. On a Claude plan, you&#39;ll hit your usage limit faster.</li><li>Vague work doesn&#39;t belong in a loop. &quot;Think of a better product strategy&quot; is not a loop. Go figure out the actual goal first.</li></ol><h2 id="start-this-week" tabindex="-1">Start this week <a class="header-anchor" href="#start-this-week" aria-label="Permalink to &quot;Start this week&quot;">​</a></h2><p>Pick one task you keep doing by hand, the kind with lots of small pieces. Paste the charter. Fill in the brackets. Run it once while you watch every step. When you trust it, put it on a schedule. The first time you wake up to work that finished overnight, you&#39;ll stop typing prompts one at a time. Just like Boris.</p><p>[圖 5]</p><p>Helped? Follow me. I share this stuff so you don&#39;t have to dig for it</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Loop Engineering 最佳入門文（1M+ views）——「You are the loop」核心洞察 + Loop Charter 六段模板 + /goal vs /loop 分野 + cron vs loop 關鍵區分（decision-maker inside），Boris Cherny 親自佐證。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>「You are the loop」</strong>：多數人自己在做 loop 的工作（prompt→check→retry），真正的 loop engineering 是讓系統做這件事</li><li><strong>Loop 5 beats</strong>：Find work → Do it → Check itself → Remember → Go again；「prompting is doing the work; loop engineering is managing the worker」</li><li><strong>Cron vs Loop 關鍵區分</strong>：cron 跑 script（固定步驟）；loop 跑 Claude（有 decision-maker 在中間）——「A script can&#39;t look at a broken test and figure out a different fix. Claude can.」</li><li><strong>/goal vs /loop 分野</strong>： <ul><li><code>/goal</code> = 有終點線（finish line），二副本機制：第一副本做、第二副本每輪後確認是否達標</li><li><code>/loop</code> = 有節拍無終點（rhythm），monitoring/scheduling 場景</li></ul></li><li><strong>Loop Charter 六段模板</strong>：GOAL / WHERE THE WORK IS / HOW TO WORK / HOW TO CHECK YOURSELF / HOW TO REMEMBER / WHEN TO STOP</li><li><strong>LOOP-STATE.md = 狀態文件</strong>：「quiet hero」——每輪讀取防止重複工作，記錄 done/blocked/needs-me 三態</li><li><strong>何時不用 loop</strong>：一次性任務、模糊目標、不值得 setup cost</li></ol><h3 id="關鍵可複製片段" tabindex="-1">關鍵可複製片段 <a class="header-anchor" href="#關鍵可複製片段" aria-label="Permalink to &quot;關鍵可複製片段&quot;">​</a></h3><p><strong>Link verification loop prompt</strong>：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/goal write a one page brief on [your topic]</span></span>
<span class="line"><span>where every claim has at least three sources and</span></span>
<span class="line"><span>every link opens to a real page that supports the claim. </span></span>
<span class="line"><span>Open each link to confirm it before you call it done.</span></span>
<span class="line"><span>Replace any source that is dead or does not back up the claim.</span></span>
<span class="line"><span>Stop only when every source on the page checks out.</span></span></code></pre></div><p><strong>Loop Charter 六段模板</strong>（填空即用）：GOAL → WHERE THE WORK IS → HOW TO WORK → HOW TO CHECK YOURSELF → HOW TO REMEMBER → WHEN TO STOP</p><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>/goal 二副本機制具體描述</strong>：「After every turn, a second copy of Claude quietly checks: are we at the goal yet? If not, it tells the first one why」——比 workspace The Loop 的描述更具體，補充 /goal 機制細節</li><li><strong>LOOP-STATE.md vs STATUS.md</strong>：本文的 <code>LOOP-STATE.md</code>（done/blocked/needs-me 三態）與 KyrieCheungYep 的 <code>progress.md</code> 同構，但加了「Read FIRST every run」明確指令——防止重跑已完成工作</li><li><strong>「Checking means evidence, not confidence」</strong> = core.md TEST 的精準口語化表達</li><li><strong>1M+ views + Boris Cherny quote</strong> = 最高公信力來源之一；但內容定位是 loop 入門，與 workspace 高度重疊</li><li><strong>三「不用 loop」條件</strong>（one-off/vague/cost）補充 unicodef1wn 的 &quot;when to skip&quot; 單條，更系統</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7/10</td><td>Loop Charter 模板直接可用；/goal 二副本機制補充；LOOP-STATE.md 三態模式</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>&quot;Prompting = doing work; Loop = managing worker&quot; 是最佳 framing；cron vs loop 區分清晰；但整體入門定位</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>Boris Cherny 第一手引述 + 1M+ views + 具體範例（link verification）；Twitter Article 上限 6</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>Loop Charter 六段有結構；/goal 二副本機制有深度；但整體入門級別</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>Loop Charter 框架 framework-agnostic；「當不用 loop」三條件普遍適用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.6/10</strong></td><td>7×0.3+6×0.2+6×0.2+6×0.15+8×0.15 = 2.1+1.2+1.2+0.9+1.2</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：/goal 二副本自查機制（每輪後 second copy 確認）+ Loop Charter 六段模板 + LOOP-STATE.md 三態（done/blocked/needs-me）+ cron vs loop 關鍵區分（decision-maker inside）直接補充 core.md The Loop + subagent-strategy.md；Boris Cherny 高公信力佐證</p>`,52)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
